function roomRequestMessages(room, participantIndex) {
  const participant = room.participants[participantIndex]; const others=room.participants.filter((_,index)=>index!==participantIndex).map((entry)=>entry.name);
  const system = [`You are ${participant.name}, one participant in a bounded collaboration with the user and ${others.join(", ")}.`, `Personality: ${participant.personality || "Respond naturally and constructively."}`, participant.systemPrompt || "", "Reply only as yourself. Engage with the latest speaker and the shared task, do not impersonate any other participant, and do not try to continue the conversation beyond this one response."].filter(Boolean).join("\n\n");
  const history = room.messages.slice(-38).map((message) => ({ role: message.participant === participantIndex ? "assistant" : "user", content: (message.speaker === "user" ? `[User]\n${message.content}` : `[${message.name}]\n${message.content}`) + formatFrozenContext(message.context) }));
  while (history.length && history[0].role === "assistant") history.shift();
  if (history.at(-1)?.role === "assistant") history.push({ role: "user", content: `[Room moderator]\nContinue the discussion with ${others.join(", ")} and the user.` });
  return [{ role: "system", content: system }, ...history];
}
