async function loadRecords(){const records=await dbAll();state.conversations=records.filter(r=>r.type==="conversation");state.runs=records.filter(r=>r.type==="eval-run").sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));const activeId=localStorage.getItem(ACTIVE_CONVERSATION_KEY);state.conversation=state.conversations.find(c=>c.id===(state.conversation?.id||activeId))||state.conversations.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];state.suites=records.filter(r=>r.type==="eval-suite").sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));state.suite=state.suites.find(s=>s.id===state.suite?.id)||state.suites[0]||defaultSuite();if(!state.suites.length)state.suites=[state.suite];if(!state.conversation){state.conversation=defaultConversation();state.conversations=[state.conversation];await dbPut(state.conversation);}localStorage.setItem(ACTIVE_CONVERSATION_KEY,state.conversation.id);const titleRetries=[];for(const conversation of state.conversations){let changed=false;if(conversation.room?.running){conversation.room.running=false;changed=true;}if(!conversation.studio){conversation.studio=defaultStudio();changed=true;}else if(conversation.studio.running){conversation.studio.running=false;changed=true;}if(conversation.studio?.pendingImage?.status==="generating"){conversation.studio.pendingImage.status="failed";conversation.studio.pendingImage.error="Reload interrupted generation; approve a new request instead";changed=true;}const titleSource=conversation.turns?.[0]?.prompt||conversation.room?.messages?.find((message)=>message.speaker==="user")?.content||conversation.studio?.chat?.messages?.find((message)=>message.role==="user")?.content||(conversation.studio?.log?.length?conversation.studio.brief:"");if(conversation.titleMode==="generating"){conversation.titleMode="failed";changed=true;}if(titleSource&&conversation.title==="Untitled field note"&&conversation.titleMode!=="manual"){conversation.title=localConversationTitle(titleSource);conversation.titleMode="failed";changed=true;}if(titleSource&&["failed","local",undefined].includes(conversation.titleMode)&&Number(conversation.titleAttempts||0)<2)titleRetries.push({conversation,titleSource});for(const entry of conversation.studio.log||[])if(entry.status==="pending"){entry.status="paused";entry.error="Interrupted by reload";changed=true;}for(const turn of conversation.turns||[])for(const result of Object.values(turn.results||{}))if(result?.status==="pending"){Object.assign(result,{status:"error",error:"Interrupted before completion",content:"",metrics:null});changed=true;}if(changed)await dbPut(conversation);}await dbPut(state.suite);syncControls();renderAll();contextBroker?.render();renderSuite();if(state.runs[0])renderEvalRun(state.runs[0]);for(const item of titleRetries)void generateConversationTitle(item.conversation,item.titleSource);}
