function currentContextResources(){const conversation=state.conversation;if(!conversation)return[];const scratch=scratchpadState(conversation);const studio=studioState(conversation);const resources=[{id:"scratchpad",label:"Scratchpad document",revision:scratch.revision,provenance:`note:${conversation.id}/scratchpad`,content:scratch.text},{id:"studio-manifest",label:"Studio manifest",revision:studio.revision,provenance:`note:${conversation.id}/studio`,content:JSON.stringify({brief:studio.brief,revision:studio.revision,files:Object.keys(studio.files),handoff:studio.handoff},null,2)},{id:"room-transcript",label:"Recent Room transcript",revision:conversation.room?.messages?.length||0,provenance:`note:${conversation.id}/room/recent`,content:JSON.stringify((conversation.room?.messages||[]).slice(-20).map(({name,speaker,content,createdAt})=>({name,speaker,content,createdAt})),null,2)}];for(const [path,content] of Object.entries(studio.files))resources.push({id:`studio-file:${path}`,label:`Studio file · ${path}`,revision:studio.revision,provenance:`note:${conversation.id}/studio/${path}`,content});for(const lane of conversation.lineup.slice(0,4)){const turns=conversation.turns.filter((turn)=>turn.lanes.some((item)=>item.id===lane.id)).slice(-12).map((turn)=>({prompt:turn.prompt,response:turn.results[lane.id]?.content||""}));resources.push({id:`branch:${lane.id}`,label:`Current branch · ${lane.model}`,revision:conversation.turns.length,provenance:`note:${conversation.id}/branch/${lane.id}`,content:JSON.stringify(turns,null,2)});}return resources;}
