$("image-model").onchange=()=>{state.selectedImageModel=$("image-model").value;renderImageCatalog();if(state.mode==="images")renderLineup();};
$("gallery-sort").onchange=renderBenchmarkGallery;
$("studio-brief").oninput=()=>{studioState().brief=$("studio-brief").value;saveConversation();};$("studio-add-agent").onclick=()=>{const studio=studioState();if(studio.agents.length>=4)return;pauseStudio();studio.agents.push({id:uid("studioAgent"),name:`Agent ${studio.agents.length+1}`,model:studio.agents.at(-1)?.model||state.catalog[0]?.id||"",role:"Frontend specialist",scope:"index.html, styles.css, app.js",personality:"Thoughtful, practical, and attentive to detail.",systemPrompt:"Make one coherent improvement and preserve working behavior."});renderStudio();saveConversation();};
$("studio-chat-composer").onsubmit=(event)=>{event.preventDefault();const text=$("studio-chat-draft").value.trim();if(text)ensureConversationTitle(state.conversation,text);let attached;try{attached=contextBroker.consume("studio");}catch(error){return toast(error.message);}void studioChat.send(attached);};
$("stop-studio-chat").onclick=()=>studioChat.stop();
$("studio-iterations").oninput=()=>{studioState().remaining=Number($("studio-iterations").value);renderStudio();saveConversation();};$("studio-duration").oninput=()=>{studioState().maxSeconds=Number($("studio-duration").value);renderStudio();saveConversation();};$("studio-output-mib").oninput=()=>{state.conversation.parameters.maxOutputMiB=Number($("studio-output-mib").value);$("max-output-mib").value=$("studio-output-mib").value;renderStudio();saveConversation();};document.querySelectorAll("[data-studio-top-up]").forEach((button)=>button.onclick=()=>{const studio=studioState();studio.remaining=Math.min(20,studio.remaining+Number(button.dataset.studioTopUp));renderStudio();saveConversation();});$("studio-resume").onclick=runStudio;$("studio-pause").onclick=()=>pauseStudio();$("studio-retry").onclick=()=>{const studio=studioState();studio.failedTurn=null;renderStudio();saveConversation();void runStudio();};$("studio-skip").onclick=()=>{const studio=studioState();if(studio.failedTurn)studio.nextAgent=(studio.failedTurn.agentIndex+1)%studio.agents.length;studio.failedTurn=null;renderStudio();saveConversation();};
$("studio-editor").oninput=()=>{const studio=studioState();const previous=studio.files[studio.activeFile]||"";const next=$("studio-editor").value;const size=studioProjectSize(studio.files)-previous.length+next.length;if(size>STUDIO_MAX_PROJECT){$("studio-editor").value=previous;$("studio-project-status").textContent=`Edit rejected: project would exceed ${STUDIO_MAX_PROJECT.toLocaleString()} characters`;$("studio-project-status").classList.add("error");return;}studio.files[studio.activeFile]=next;studio.revision+=1;studio.failedTurn=null;$("studio-project-status").textContent=`Revision ${studio.revision} · ${Object.keys(studio.files).length}/${STUDIO_MAX_FILES} files · ${size.toLocaleString()}/${STUDIO_MAX_PROJECT.toLocaleString()} characters · browser-local only`;$("studio-project-status").classList.remove("error");scheduleStudioPreview();saveConversation();};
$("studio-javascript").onchange=()=>{studioState().javascriptEnabled=$("studio-javascript").checked;renderStudioPreview();saveConversation();};document.querySelectorAll("[data-canvas-size]").forEach((button)=>button.onclick=()=>{state.studioCanvasSize=button.dataset.canvasSize;document.querySelectorAll("[data-canvas-size]").forEach((item)=>item.classList.toggle("active",item===button));renderStudioPreview();});
$("studio-snapshot").onclick=()=>{snapshotStudio();renderStudio();saveConversation();toast("Project snapshot saved")};$("studio-rollback").onclick=()=>{const studio=studioState();const snapshot=studio.snapshots.at(-1);if(!snapshot)return toast("No snapshot is available");if(!confirm(`Roll back to “${snapshot.label}”? Current unsnapshotted edits will be replaced.`))return;pauseStudio(false);studio.snapshots.pop();const before=studio.revision;studio.files=clone(snapshot.files);studio.activeFile=studio.files[snapshot.activeFile]!==undefined?snapshot.activeFile:Object.keys(studio.files)[0];studio.revision+=1;studio.nextAgent=Number.isInteger(snapshot.nextAgent)?snapshot.nextAgent:studio.nextAgent;studio.handoff=snapshot.handoff||studio.handoff;studio.failedTurn=null;studio.ledger.push({id:uid("studioLedger"),createdAt:now(),agent:"User",tool:"restore_snapshot",status:"applied",baseRevision:before,resultRevision:studio.revision,files:Object.keys(studio.files),summary:`Restored ${snapshot.label}`});renderStudio();saveConversation();toast("Rolled back to latest snapshot")};$("studio-download").onclick=()=>{const studio=studioState();exportFile(`${safeName(state.conversation.title)}-project.json`,"application/json",JSON.stringify({format:"routetok-iteration-studio",version:1,exportedAt:now(),brief:studio.brief,files:studio.files},null,2));};$("studio-reset").onclick=()=>{if(!confirm("Reset all virtual project files to the starter?"))return;pauseStudio(false);const studio=studioState();snapshotStudio("Before project reset",studio);const before=studio.revision;studio.files=clone(STUDIO_STARTER);studio.activeFile="index.html";studio.revision+=1;studio.failedTurn=null;studio.handoff=null;studio.ledger.push({id:uid("studioLedger"),createdAt:now(),agent:"User",tool:"reset_project",status:"applied",baseRevision:before,resultRevision:studio.revision,files:Object.keys(studio.files),summary:"Reset virtual project"});renderStudio();saveConversation();toast("Virtual project reset")};
$("studio-canvas-resizer").onpointerdown=(event)=>{if(innerWidth<=900)return;const startX=event.clientX;const startWidth=state.studioCanvasWidth;$("studio-canvas-resizer").setPointerCapture(event.pointerId);$("studio-canvas-resizer").onpointermove=(move)=>setStudioCanvasWidth(startWidth+startX-move.clientX);$("studio-canvas-resizer").onpointerup=()=>{$("studio-canvas-resizer").onpointermove=null;$("studio-canvas-resizer").onpointerup=null;};};$("studio-canvas-resizer").onkeydown=(event)=>{if(event.key==="ArrowLeft"){event.preventDefault();setStudioCanvasWidth(state.studioCanvasWidth+24);}else if(event.key==="ArrowRight"){event.preventDefault();setStudioCanvasWidth(state.studioCanvasWidth-24);}else if(event.key==="Home"){event.preventDefault();setStudioCanvasWidth(320);}else if(event.key==="End"){event.preventDefault();setStudioCanvasWidth(1000);}};
document.addEventListener("keydown",(e)=>{if(e.key==="Escape"){if(contextBroker.hasPickerOpen())contextBroker.closePicker();else if(panelManager.closeDrawer()){}else if(state.studioController)pauseStudio();else if(state.roomController)pauseRoom();else if(state.controllers.size)stopAll();else closePanels();}if((e.ctrlKey||e.metaKey)&&e.key==="Enter"&&!$("chat-view").hidden){e.preventDefault();$("composer").requestSubmit();}if((e.ctrlKey||e.metaKey)&&e.key==="Enter"&&!$("room-view").hidden){e.preventDefault();$("room-composer").requestSubmit();}if((e.ctrlKey||e.metaKey)&&e.key==="Enter"&&!$("studio-view").hidden&&document.activeElement===$("studio-chat-draft")){e.preventDefault();$("studio-chat-composer").requestSubmit();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="n"){e.preventDefault();createConversation();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();closePanels();$("library").classList.add("open");$("toggle-library").setAttribute("aria-expanded","true");$("conversation-search").focus();}});
window.addEventListener("pagehide",()=>{if(state.conversation){if(state.conversation.studio)state.conversation.studio.running=false;void dbPut(clone(state.conversation));}state.studioController?.abort();state.controllers.forEach(c=>c.abort());state.imageController?.abort();state.imageUrls.forEach((url)=>URL.revokeObjectURL(url));});setScratchpadWidth(state.scratchpadWidth);setStudioCanvasWidth(state.studioCanvasWidth);init();
